[tool_use Bash: {"command": "python - <<'EOF'
import ast, pathlib
missing = []
for path in sorted(pathlib.Path("ledgerkit").rglob("*.py")):
    tree = ast.parse(path.read_text())
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith("_"):
            args = node.args.posonlyargs + node.args.args + node.args.kwonlyargs
            bad = [a.arg for a in args if a.annotation is None and a.arg not in ("self", "cls")]
            if bad or node.returns is None:
                missing.append(f"{path}:{node.lineno} {node.name} params={bad} returns={'ok' if node.returns else 'MISSING'}")
print("\n".join(missing) or "all public functions fully annotated")
EOF", "description": "Check public functions carry full type annotations"}]
